const daysSince = (v) => { const t = Date.parse(v); return isNaN(t) ? null : (Date.now() - t) / 86400000; };
const daysUntil = (v) => { const t = Date.parse(v); return isNaN(t) ? null : (t - Date.now()) / 86400000; };
const has = (v) => v !== undefined && v !== null && String(v).trim() !== '';
const cfg = $('Settings').first().json.config;
return $input.all().filter((item) => {
  const r = item.json;
  return ((!has(r.reminded) && daysUntil(r.session_date) !== null && daysUntil(r.session_date) > 0 && daysUntil(r.session_date) <= 1.5) || (has(r.reminded) && !has(r.followed_up) && daysSince(r.session_date) !== null && daysSince(r.session_date) >= 1));
}).slice(0, 50);

